cat > /tmp/patch_multiplexer.go << 'EOF'
package main

import (
	"fmt"
	"io/ioutil"
	"strings"
)

func main() {
	content, _ := ioutil.ReadFile("/app/lib/multiplexer/multiplexer.go")
	text := string(content)

	// Add ProtoProxyV2 to the Protocol enum
	text = strings.Replace(text,
		`	// ProtoPostgres is PostgreSQL wire protocol
	ProtoPostgres
)`,
		`	// ProtoPostgres is PostgreSQL wire protocol
	ProtoPostgres
	// ProtoProxyV2 is a HAProxy proxy protocol version 2
	ProtoProxyV2
)`,
		1)

	// Add ProtoProxyV2 to protocolStrings
	text = strings.Replace(text,
		`	ProtoPostgres: "Postgres",
}`,
		`	ProtoPostgres: "Postgres",
	ProtoProxyV2:  "ProxyV2",
}`,
		1)

	// Add proxyV2Prefix before the detectProto function
	text = strings.Replace(text,
		`var (
	proxyPrefix = []byte{'P', 'R', 'O', 'X', 'Y'}
	sshPrefix   = []byte{'S', 'S', 'H'}
	tlsPrefix   = []byte{0x16}
)`,
		`var (
	proxyPrefix = []byte{'P', 'R', 'O', 'X', 'Y'}
	proxyV2Prefix = []byte{0x0D, 0x0A, 0x0D, 0x0A, 0x00, 0x0D, 0x0A, 0x51, 0x55, 0x49, 0x54, 0x0A}
	sshPrefix   = []byte{'S', 'S', 'H'}
	tlsPrefix   = []byte{0x16}
)`,
		1)

	ioutil.WriteFile("/app/lib/multiplexer/multiplexer.go", []byte(text), 0644)
	fmt.Println("Patched multiplexer.go")
}
EOF
